def do_GET(self) -> None:  # noqa: N802
    try:
        parsed = urlparse(self.path)
        path = parsed.path.rstrip("/") or "/"
        if path in ("/health", "/healthz"):
            self._send_json(200, {"status": "ok"})
            return
        if not path.startswith("/v1"):
            self._send_error(404, f"无此路径: {path}")
            return
        # 仅 /v1 路由受租户头约束
        if (
            path
            == "/v1/trust/presentation-sync/receipt/consumptions"
            and self.headers.get("X-Tenant-ID") == ""
        ):
            raise ValidationError("请求非法")
        tenant = self._tenant_id()
        if path == "/v1/audit":
            self._get_audit(tenant, parsed.query)
        elif path == "/v1/audit/manifest":
            self._get_audit_manifest(tenant, parsed.query)
        elif path == "/v1/presentation-requests" or (
            path.startswith("/v1/presentation-requests/")
        ):
            rest = unquote(
                path[len("/v1/presentation-requests/") :]
            ) if path.startswith("/v1/presentation-requests/") else ""
            if rest.endswith("/history"):
                request_id = rest[: -len("/history")]
                if not request_id:
                    self._send_error(404, f"无此路径: {path}")
                else:
                    self._get_presentation_request_history(
                        tenant, request_id, parsed.query
                    )
            elif not rest:
                self._send_error(404, f"无此路径: {path}")
            else:
                self._get_presentation_request(tenant, rest)
        elif path.startswith("/v1/dids/") and path.endswith(
            "/document"
        ):
            did = unquote(
                path[len("/v1/dids/") : -len("/document")]
            )
            self._get_did_document(tenant, did, parsed.query)
        elif path.startswith("/v1/dids/") and "/keys/" in path and (
            path.endswith("/status")
            or path.endswith("/keys/revocations")
            or path.endswith("/keys/history")
            or path.endswith("/keys/rotations")
        ):
            middle = path[len("/v1/dids/") :]
            did_raw, sep, rest = middle.partition("/keys/")
            did = unquote(did_raw)
            if rest == "revocations":
                self._get_key_revocations(
                    tenant, did, parsed.query
                )
            elif rest == "history":
                self._get_key_history(
                    tenant, did, parsed.query
                )
            elif rest == "rotations":
                self._get_key_rotations(
                    tenant, did, parsed.query
                )
            else:
                key_version = unquote(
                    rest[: -len("/status")]
                )
                self._get_key_version_status(
                    tenant, did, key_version
                )
        elif path.startswith("/v1/dids/") and path.endswith("/status"):
            did = unquote(
                path[len("/v1/dids/") : -len("/status")]
            )
            self._get_did_status(tenant, did)
        elif path.startswith("/v1/dids/") and path.endswith("/history"):
            did = unquote(
                path[len("/v1/dids/") : -len("/history")]
            )
            self._get_did_history(tenant, did, parsed.query)
        elif path.startswith("/v1/dids/"):
            self._get_did(tenant, unquote(path[len("/v1/dids/") :]))
        elif path.startswith("/v1/credential-schemas/"):
            schema_suffix = path[len("/v1/credential-schemas/") :]
            if schema_suffix.endswith("/status"):
                self._get_credential_schema_status(
                    tenant,
                    schema_suffix[: -len("/status")],
                    parsed.query,
                )
            elif schema_suffix.endswith("/history"):
                self._get_credential_schema_history(
                    tenant,
                    schema_suffix[: -len("/history")],
                    parsed.query,
                )
            else:
                self._get_credential_schema(
                    tenant, schema_suffix, parsed.query
                )
        elif path.startswith("/v1/credentials/") and path.endswith(
            "/status/history"
        ):
            credential_id = unquote(
                path[
                    len("/v1/credentials/") : -len("/status/history")
                ]
            )
            self._get_credential_status_history(
                tenant, credential_id, parsed.query
            )
        elif path.startswith("/v1/credentials/") and path.endswith(
            "/status"
        ):
            credential_id = unquote(
                path[len("/v1/credentials/") : -len("/status")]
            )
            self._get_credential_status(tenant, credential_id)
        elif path.startswith("/v1/credentials/"):
            self._get_credential(
                tenant, unquote(path[len("/v1/credentials/") :])
            )
        elif path == "/v1/trust/anchors":
            self._get_trust_anchor_discovery(tenant, parsed.query)
        elif path == "/v1/trust/anchor-changes":
            self._get_trust_anchor_changes(tenant, parsed.query)
        elif path == "/v1/trust/ac-proof":
            self._get_trust_ac_proof(tenant, parsed.query)
        elif path == "/v1/trust/anchor-changes/sync-history":
            self._get_trust_anchor_changes_sync_history(
                tenant, parsed.query
            )
        elif path == "/v1/trust/anchor-changes/synced-state":
            self._get_trust_anchor_changes_synced_state(
                tenant, parsed.query
            )
        elif path == "/v1/trust/presentation-sync/history":
            self._get_trust_presentation_sync_history(
                tenant, parsed.query
            )
        elif path == "/v1/trust/presentation-sync/receipt":
            self._get_trust_presentation_sync_receipt(
                tenant, parsed.query
            )
        elif (
            path
            == "/v1/trust/presentation-sync/receipt/consumptions"
        ):
            self._get_trust_presentation_sync_receipt_consumptions(
                tenant, parsed.query
            )
        elif path == "/v1/trust/anchors/snapshot":
            self._get_trust_anchor_snapshot(tenant, parsed.query)
        elif path == "/v1/trust/dids/deactivations":
            self._get_trust_did_deactivations(tenant, parsed.query)
        elif (
            path
            == (
                "/v1/trust/credential-status/receipt/consumptions"
                "/export"
            )
        ):
            self._get_trust_credential_status_receipt_consumptions_export(
                tenant, parsed.query
            )
        elif (
            path
            == "/v1/trust/credential-status/receipt/consumptions"
            "/manifest"
        ):
            self._get_trust_credential_status_receipt_consumptions_manifest(
                tenant, parsed.query
            )
        elif (
            path
            == "/v1/trust/credential-status/receipt-sync/history"
        ):
            self._get_trust_credential_status_receipt_sync_history(
                tenant, parsed.query
            )
        elif (
            path
            == "/v1/trust/credential-status/receipt-sync/receipt"
        ):
            self._get_trust_credential_status_receipt_sync_receipt(
                tenant, parsed.query
            )
        elif (
            path
            == "/v1/trust/credential-status/receipt-sync/receipt"
            "/consumptions"
        ):
            self._get_trust_credential_status_receipt_sync_receipt_consumptions(
                tenant, parsed.query
            )
        elif (
            path
            == "/v1/trust/credential-status/receipt-sync/receipt"
            "/consumptions/export"
        ):
            self._get_trust_credential_status_receipt_sync_receipt_consumptions_export(
                tenant, parsed.query
            )
        elif (
            path
            == "/v1/trust/credential-status/receipt-sync/receipt"
            "/consumptions/manifest"
        ):
            self._get_trust_credential_status_receipt_sync_receipt_consumptions_manifest(
                tenant, parsed.query
            )
        elif (
            path
            == "/v1/trust/credential-status/receipt/consumptions"
        ):

def build_handler(store: VCStore) -> type:
    """构造绑定给定 store 的请求处理器类。"""

    class Handler(BaseHTTPRequestHandler):
        server_version = "VCBackend/0.1"

        # ------------------------------------------------------------ #
        # 响应工具
        # ------------------------------------------------------------ #
        def _send_json(self, status: int, payload: Any) -> None:
            body = _json_dumps(payload)
            self.send_response(status)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def _send_error(self, status: int, message: str) -> None:
            self._send_json(status, {"error": message})

        def _send_invalid(self, reason: str) -> None:
            """verify 端点统一失败响应：HTTP 200 + valid:false + 中文原因。"""
            self._send_json(200, {"valid": False, "reason": reason})

        def _tenant_id(self) -> str:
            """解析 X-Tenant-ID：缺省 default；显式空串 400。"""
            raw = self.headers.get("X-Tenant-ID")
            if raw is None:
                return DEFAULT_TENANT
            if raw == "":
                raise ValidationError("X-Tenant-ID 不能为空")
            return raw

        def _idempotency_key(self) -> Optional[str]:
            """解析 Idempotency-Key：缺省 None；重复提供或格式非法 400。

            键值区分大小写，须为 1-64 个 ASCII 字母、数字、下划线或
            连字符；空值、非法字符、超长或重复提供该头均 400。
            """
            values = self.headers.get_all("Idempotency-Key")
            if not values:
                return None
            if len(values) > 1:
                raise ValidationError("Idempotency-Key 头只能提供一次")
            key = values[0]
            if not _IDEMPOTENCY_KEY_RE.fullmatch(key):
                raise ValidationError(
                    "Idempotency-Key 必须为 1-64 个 ASCII 字母、数字、"
                    "下划线或连字符"
                )
            return key

        def _read_json(self) -> Dict[str, Any]:
            length = int(self.headers.get("Content-Length") or 0)
            raw = self.rfile.read(length) if length else b""
            try:
                data = json.loads(raw.decode("utf-8")) if raw else None
            except (UnicodeDecodeError, json.JSONDecodeError) as exc:
                raise ValidationError(f"请求体不是合法 JSON: {exc}") from exc
            if not isinstance(data, dict):
                raise ValidationError("请求体必须为 JSON 对象")
            return data

        def _read_optional_json(self) -> Dict[str, Any]:
            """读取可选请求体：空体等价于 {}，非空时须为 JSON 对象。"""
            length = int(self.headers.get("Content-Length") or 0)
            raw = self.rfile.read(length) if length else b""
            if not raw:
                return {}
            try:
                data = json.loads(raw.decode("utf-8"))
            except (UnicodeDecodeError, json.JSONDecodeError) as exc:
                raise ValidationError(f"请求体不是合法 JSON: {exc}") from exc
            if not isinstance(data, dict):
                raise ValidationError("请求体必须为 JSON 对象")
            return data

        # ------------------------------------------------------------ #
        # 路由
        # ------------------------------------------------------------ #

def _get_audit(self, tenant: str, query: str) -> None:            # GET /v1/audit?limit=&after=：租户内按 seq 升序。
    # limit 缺省 50，须为 1..200 的整数；after 缺省 0，须为
    # 非负整数；非法一律 400。返回 events 与 next_after，
    # 空页 next_after 保持 after。
    params = parse_qs(query, keep_blank_values=True)
    limit_values = params.get("limit")
    after_values = params.get("after")
    if limit_values is not None:
        if len(limit_values) != 1:
            raise ValidationError("查询参数 limit 只能提供一次")
        limit = _parse_nonneg_int(limit_values[0], "limit")
        if not 1 <= limit <= 200:
            raise ValidationError("查询参数 limit 须在 1 到 200 之间")
    else:
        limit = 50
    if after_values is not None:
        if len(after_values) != 1:
            raise ValidationError("查询参数 after 只能提供一次")
        after = _parse_nonneg_int(after_values[0], "after")
    else:
        after = 0

    events, next_after = store.list_audit(tenant, after, limit)
    self._send_json(
        200,
        {
            "events": [
                {
                    "seq": event.seq,
                    "timestamp": event.timestamp,
                    "tenant_id": event.tenant_id,
                    "action": event.action,
                    "resource_type": event.resource_type,
                    "resource_id": event.resource_id,
                }
                for event in events
            ],
            "next_after": next_after,
        },
    )

# 审计清单事件固定六字段（与 GET /v1/audit 完全一致）。
_AUDIT_EVENT_FIELDS = (
    "seq",
    "timestamp",
    "tenant_id",
    "action",
    "resource_type",
    "resource_id",
)

def _audit_event_obj(self, event: Any) -> Dict[str, Any]:
    return {
        "seq": event.seq,
        "timestamp": event.timestamp,
        "tenant_id": event.tenant_id,
        "action": event.action,
        "resource_type": event.resource_type,
        "resource_id": event.resource_id,
    }

def _parse_audit_manifest_query(
    self, query: str
) -> Dict[str, Any]:
    # 仅允许 snapshot、signer_did、after、limit，各一次。
    # snapshot 必填非负整数；signer_did 必填非空串；after 缺省
    # 0 且非负；limit 缺省 50 且限 1..200；after 不得大于
    # snapshot。任何空值、重复、未知参数、非 ASCII 数字、符号、
    # 小数均抛 ValidationError（400，仅含非空中文 error）。
    params = parse_qs(query, keep_blank_values=True)
    allowed = {"snapshot", "signer_did", "after", "limit"}
    unknown = sorted(set(params) - allowed)
    if unknown:
        raise ValidationError(
            f"不支持的查询参数: {', '.join(unknown)}"
        )

    def _single(name: str) -> Optional[str]:
        values = params.get(name)
        if values is None:
            return None
        if len(values) != 1:
            raise ValidationError(
                f"查询参数 {name} 只能提供一次"
            )
        return values[0]

    snapshot_raw = _single("snapshot")
    if snapshot_raw is None:
        raise ValidationError("查询参数 snapshot 必填")
    snapshot = _parse_nonneg_int(snapshot_raw, "snapshot")

    signer_did = _single("signer_did")
    if signer_did is None or not signer_did:
        raise ValidationError(
            "查询参数 signer_did 必填且必须为非空字符串"
        )

    after_raw = _single("after")
    after = (
        _parse_nonneg_int(after_raw, "after")
        if after_raw is not None
        else 0
    )

    limit_raw = _single("limit")
    if limit_raw is not None:
        limit = _parse_nonneg_int(limit_raw, "limit")
        if not 1 <= limit <= 200:
            raise ValidationError(
                "查询参数 limit 须在 1 到 200 之间"
            )
    else:
        limit = 50

    if after > snapshot:
        raise ValidationError(
            "查询参数 after 不得大于 snapshot"
        )

def _next_local_credential_status_cursor_locked(
    self, tenant_id: str
) -> int:
    """分配租户内下一个持久化凭证状态历史游标（正整数，递增）。"""
    cursor = (
        self._local_credential_status_history_cursors.get(tenant_id, 0)
        + 1
    )
    self._local_credential_status_history_cursors[tenant_id] = cursor
    return cursor

def _backfill_local_credential_status_history_locked(self) -> None:
    """加载迁移：为有状态但无历史的本地凭证补一条兼容项（内存态）。

    对每个租户内已有状态行（status 为 active/revoked）、但该凭证
    没有任何状态历史项的旧状态，按 (租户, credential_id) 的稳定顺序
    补录一条内容取自状态行的兼容事件：active 事件 reason/revoked_at
    为 None；revoked 事件保存裁剪 reason 与 revoked_at；cursor 为该
    租户内新分配的持久化正整数，audit_seq/audit_timestamp 均为 None
    （无法追溯原始审计事件）。

    仅在内存中补录：兼容项随下一次任意原子写一并落盘；若此后无写
    操作则重启时按相同顺序重建，cursor 稳定。
    """
    for tenant_id in sorted(self._tenants):
        bucket = self._tenants[tenant_id]
        history = bucket.setdefault(
            "local_credential_status_history", {}
        )
        for credential_id in sorted(bucket.get("credentials", {})):
            rec = bucket["credentials"][credential_id]
            status = rec.get("status")
            if status not in ("active", "revoked"):
                continue
            entries = history.setdefault(credential_id, [])
            if entries:
                continue
            if status == "revoked":
                reason = rec.get("revoke_reason")
                revoked_at = rec.get("revoked_at")
            else:
                reason = None
                revoked_at = None
            entries.append(
                {
                    "status": status,
                    "reason": reason,
                    "updated_at": rec.get("status_updated_at"),
                    "revoked_at": revoked_at,
                    "cursor": (
                        self._next_local_credential_status_cursor_locked(
                            tenant_id
                        )
                    ),
                    "audit_seq": None,
                    "audit_timestamp": None,
                }
            )

@staticmethod
def _imported_credential_record(
    issuer_did: str, credential_id: str, row: Dict[str, Any]
) -> ImportedCredentialRecord:
    return ImportedCredentialRecord(
        issuer_did=issuer_did,
        credential_id=credential_id,
        body=row["body"],
        signature=row["signature"],
    )

@staticmethod
def _credential_body_field_error(
    body: Any,
) -> Tuple[Optional[str], int]:
    """校验外部凭证 body 字段，返回 (中文错误原因, 锚点版本)。

    规则与 :meth:`verify_trust_credential` 的凭证字段部分完全一致：
    body 须含 credential_id/issuer_did/subject_did/issued_at 非空
    字符串、claims 对象；issuer_key_version 可省略（按版本 1），
    提供时须为非布尔正整数。通过时错误原因为 None。
    """
    if not isinstance(body, dict):
        return "字段 body 必须为 JSON 对象", 1
    required_str = (
        "credential_id",
        "issuer_did",
        "subject_did",
        "issued_at",
    )
    for field in required_str:
        if field not in body:
            return f"凭证缺少字段: {field}", 1
        value = body[field]
        if not isinstance(value, str) or not value:
            return f"凭证字段 {field} 必须为非空字符串", 1
    if "claims" not in body:
        return "凭证缺少字段: claims", 1
    if not isinstance(body["claims"], dict):
        return "凭证字段 claims 必须为 JSON 对象", 1
    key_version = 1
    if "issuer_key_version" in body:
        version_obj = body["issuer_key_version"]
        if (
            not isinstance(version_obj, int)
            or isinstance(version_obj, bool)
            or version_obj < 1
        ):
            return "凭证字段 issuer_key_version 必须为正整数", 1
        key_version = version_obj
    return None, key_version

def import_trust_credential(
    self,
    tenant_id: str,
    data: Any,
) -> Dict[str, Any]:
    """导入一条外部凭证，返回结果字典。

    请求结构与凭证字段规则同 :meth:`verify_trust_credential`，但错误
    分类不同：

def _get_credential(self, tenant: str, credential_id: str) -> None:
    record = store.get_credential(tenant, credential_id)
    self._send_json(
        200,
        {
            "credential_id": record.credential_id,
            "body": record.body,
            "signature": record.signature,
        },
    )

@staticmethod
def _status_payload(record: Any) -> Dict[str, Any]:
    return {
        "credential_id": record.credential_id,
        "status": record.status,
        "updated_at": record.updated_at,
    }

def _put_credential_status(
    self, tenant: str, credential_id: str
) -> None:
    # 请求体必须恰为 {"status": "active"} 或
    # {"status": "suspended", "reason": "原因"}：缺字段、取值
    # 非法、多余字段一律 400；reason 须为字符串且首尾裁剪后为
    # 1..256 个 Unicode 码点，否则 400。
    data = self._read_json()
    if "status" not in data:
        raise ValidationError("缺少字段: status")
    status = data["status"]
    if status == "active":
        extra = sorted(set(data) - {"status"})
        if extra:
            raise ValidationError(
                f"多余字段: {', '.join(extra)}"
            )
        record, created = store.set_credential_status(
            tenant, credential_id, "active"
        )
    elif status == "suspended":
        extra = sorted(set(data) - {"status", "reason"})
        if extra:
            raise ValidationError(
                f"多余字段: {', '.join(extra)}"
            )
        if "reason" not in data:
            raise ValidationError("缺少字段: reason")
        reason = data["reason"]
        if not isinstance(reason, str):
            raise ValidationError("字段 reason 必须为字符串")
        reason = reason.strip()
        if not reason:
            raise ValidationError("字段 reason 裁剪后不能为空")
        if len(reason) > 256:
            raise ValidationError(
                "字段 reason 裁剪后须为 1 到 256 个 Unicode 码点"
            )
        record, created = store.set_credential_status(
            tenant, credential_id, "suspended", reason=reason
        )
    else:
        raise ValidationError(
            "字段 status 非法: "
            f"{status!r}（仅支持 active、suspended）"
        )
    # 无状态首次登记 active 为 201；暂停/恢复转换与同状态幂等
    # 均为 200（幂等保持首次 updated_at）。
    self._send_json(
        201 if created else 200, self._status_payload(record)
    )

def _put_credential_status_batch(self, tenant: str) -> None:
    # PUT /v1/credentials/status-batch：整批原子登记/暂停/恢复。
    # 请求体须恰为 {"items": [项...]}，items 为 1..100 个对象；
    # 每项恰含 credential_id（必填非空字符串，批内不重复）、
    # status（仅 active/suspended），suspended 项另须 reason
    # （字符串且首尾裁剪后 1..256 个 Unicode 码点），active 项
    # 不接受 reason。空体、非法 JSON、非对象、外层缺/多字段、
    # items 非数组/空/超限、项缺/多字段或类型错误、credential_id
    # 缺失/为空/批内重复、status 取值非法、reason 缺失或非法均
    # 400 且非空 error；显式空 X-Tenant-ID 400。先校验租户与全部
    # 请求格式，再按输入顺序逐项检查凭证存在性（未知或他租户
    # 404）与状态冲突（revoked 终态、暂停原因不同均 409），首个
    # 失败项决定响应，错误整批不落盘。成功 200 仅返
    # {"results": [...]}，与输入等长同序，每项同单张状态响应
    # （credential_id、status、updated_at）；全部状态、历史、
    # 游标与审计同一次原子写，失败 500 整体回滚。
    data = self._read_json()
    if set(data) != {"items"}:
        missing = "items" if "items" not in data else None
        if missing is not None:
            raise ValidationError("缺少字段: items")
        extra = ", ".join(sorted(set(data) - {"items"}))
        raise ValidationError(f"多余字段: {extra}")
    items = data["items"]
    if not isinstance(items, list):
        raise ValidationError("字段 items 必须为数组")
    if not 1 <= len(items) <= 100:
        raise ValidationError(
            "字段 items 须包含 1 到 100 个请求项"
        )
    parsed_items: List[Tuple[str, str, Any]] = []
    seen: set[str] = set()
    for index, item in enumerate(items):
        prefix = f"items[{index}]"
        if not isinstance(item, dict):
            raise ValidationError(f"{prefix} 必须为 JSON 对象")
        allowed = {"credential_id", "status", "reason"}
        unknown = sorted(set(item) - allowed)
        if unknown:
            raise ValidationError(
                f"{prefix} 多余字段: {', '.join(unknown)}"
            )
        if "credential_id" not in item:
            raise ValidationError(
                f"{prefix} 缺少字段: credential_id"
            )
        credential_id = item["credential_id"]
        if not isinstance(credential_id, str) or not credential_id:
            raise ValidationError(
                f"{prefix} 字段 credential_id 必须为非空字符串"
            )
        if credential_id in seen:
            raise ValidationError(
                f"{prefix} credential_id 批内重复: "
                f"{credential_id}"
            )
        seen.add(credential_id)
        if "status" not in item:
            raise ValidationError(f"{prefix} 缺少字段: status")
        status = item["status"]
        if status not in ("active", "suspended"):
            raise ValidationError(
                f"{prefix} 字段 status 非法: "
                f"{status!r}（仅支持 active、suspended）"
            )
        if status == "active":
            # active 项不接受 reason。
            if "reason" in item:
                raise ValidationError(
                    f"{prefix} 多余字段: reason"
                )
            parsed_items.append(
                (credential_id, "active", REASON_UNSET)
            )
            continue
        if "reason" not in item:
            raise ValidationError(f"{prefix} 缺少字段: reason")
        reason = item["reason"]
        if not isinstance(reason, str):
            raise ValidationError(
                f"{prefix} 字段 reason 必须为字符串"
            )
        reason = reason.strip()
        if not reason:
            raise ValidationError(
                f"{prefix} 字段 reason 裁剪后不能为空"
            )
        if len(reason) > 256:
            raise ValidationError(
                f"{prefix} 字段 reason 裁剪后须为 1 到 256 个"
                " Unicode 码点"
            )
        parsed_items.append((credential_id, "suspended", reason))

    records = store.set_credential_status_batch(
        tenant, parsed_items
    )
    self._send_json(
        200,
        {
            "results": [
                self._status_payload(record) for record in records
            ]
        },
    )

